// Subject converts this description into the form the runner uses, and
// reports anything wrong with it — no constructor, or two.
func (h ContractHarness[T]) Subject() (suite.Subject[Contract], error) {
	build, err := suite.OneCtor(h.Name, h.New, h.Start)
	if err != nil {
		return suite.Subject[Contract]{}, err
	}
	out := suite.Subject[Contract]{
		Name:     h.Name,
		Provides: h.Provide,
		New:      func(tb testing.TB) Contract { return build(tb) },
		Oracle:   h.Oracle,
		Serial:   h.Serial,
		Excused:  suite.ExcuseSet(h.Excuse),
	}
	if len(h.Induce) > 0 {
		out.Induces = make(map[error]func(testing.TB, Contract), len(h.Induce))
		for sentinel, trigger := range h.Induce {
			out.Induces[sentinel] = func(tb testing.TB, s Contract) {
				trigger(legs.AsBuilt[T](tb, h.Name, s))
			}
		}
	}
	if err := suite.ExclusivePair(h.Name, "Recover", "StartRecover",
		h.Recover != nil, h.StartRecover != nil); err != nil {
		return suite.Subject[Contract]{}, err
	}
	if reopen := h.Recover; reopen != nil {
		out.Recover = func(tb testing.TB, prior Contract) Contract {
			return reopen(legs.AsBuilt[T](tb, h.Name, prior))
		}
	}
	if reopen := h.StartRecover; reopen != nil {
		out.Recover = func(tb testing.TB, prior Contract) Contract {
			return reopen(tb, legs.AsBuilt[T](tb, h.Name, prior))
		}
	}
	return out, nil
}

func (h ContractHarness[T]) applyTo(rc *contractRunConfig) {
	rc.AddSubject(h.Subject())
}

